package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.MapperConfig;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospector;
import com.fasterxml.jackson.databind.jsontype.NamedType;
import com.fasterxml.jackson.databind.jsontype.SubtypeResolver;
import java.io.*;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for StdSubtypeResolver#collectAndResolveSubtypesByTypeId
 */
public class StdSubtypeResolver_collectAndResolveSubtypesByTypeId_TriageGen2Test {

    private StdSubtypeResolver subtypeResolver;
    private MapperConfig<?> mockConfig;
    private AnnotationIntrospector mockAi;
    private AnnotatedMember mockProperty;
    private JavaType mockBaseType;

    // Test hierarchy
    public static class Base {}
    public static class Sub extends Base {}
    public static class Unrelated {}

    @Before
    public void setUp() {
        subtypeResolver = new StdSubtypeResolver();
        mockConfig = mock(MapperConfig.class);
        mockAi = mock(AnnotationIntrospector.class);
        mockProperty = mock(AnnotatedMember.class);
        mockBaseType = mock(JavaType.class);

        when(mockConfig.getAnnotationIntrospector()).thenReturn(mockAi);
    }

    /**
     * Tests the baseline scenario: no annotations, no registered subtypes.
     * Covers the initial root type resolution and the empty check for subtypes/registrations.
     */
    @Test
    public void testCollectSubtypes_MinimalCase() {
        when(mockBaseType.getRawClass()).thenReturn(Base.class);
        when(mockAi.findSubtypes(mockProperty)).thenReturn(null);

        Collection<NamedType> result = subtypeResolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        // Should at least contain the root type itself via _combineNamedAndUnnamed logic
        boolean foundBase = false;
        for (NamedType nt : result) {
            if (nt.getType().equals(Base.class)) {
                foundBase = true;
                break;
            }
        }
        assertTrue("Result should contain the base type", foundBase);
    }

    /**
     * Tests the scenario where subtypes are provided via AnnotationIntrospector.
     * Covers the 'ai.findSubtypes(property)' branch.
     */
    @Test
    public void testCollectSubtypes_FromAnnotation() {
        when(mockBaseType.getRawClass()).thenReturn(Base.class);

        // Mock annotation finding Sub.class
        NamedType annotatedSubtype = new NamedType(Sub.class, "sub");
        when(mockAi.findSubtypes(mockProperty)).thenReturn(Collections.singletonList(annotatedSubtype));

        Collection<NamedType> result = subtypeResolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        boolean foundSub = result.stream().anyMatch(nt -> nt.getType().equals(Sub.class));
        assertTrue("Should have found subtype from annotations", foundSub);
    }

    /**
     * Tests the scenario where subtypes are provided via explicit registration.
     * Covers the '_registeredSubtypes != null' branch and 'rawBase.isAssignableFrom' branch.
     */
    @Test
    public void testCollectSubtypes_FromRegistration() {
        when(mockBaseType.getRawClass()).thenReturn(Base.class);
        when(mockAi.findSubtypes(mockProperty)).thenReturn(null);

        // Register a valid subtype and an invalid (unrelated) subtype
        subtypeResolver.registerSubtypes(Sub.class);
        subtypeResolver.registerSubtypes(Unrelated.class);

        Collection<NamedType> result = subtypeResolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        boolean foundSub = result.stream().anyMatch(nt -> nt.getType().equals(Sub.class));
        boolean foundUnrelated = result.stream().anyMatch(nt -> nt.getType().equals(Unrelated.class));

        assertTrue("Should contain registered subtype of Base", foundSub);
        assertFalse("Should NOT contain unrelated class", foundUnrelated);
    }

    /**
     * Tests the precedence: Annotation subtypes should be processed after root but before registered ones.
     * (Note: The code processes Root -> Annotations -> Registered).
     * This test ensures the logic flows through all three main blocks.
     */
    @Test
    public void testCollectSubtypes_FullPrecedenceFlow() {
        when(mockBaseType.getRawClass()).thenReturn(Base.class);

        // 1. Annotation subtype
        NamedType annotatedSub = new NamedType(Sub.class, "annotated");
        when(mockAi.findSubtypes(mockProperty)).thenReturn(Collections.singletonList(annotatedSub));

        // 2. Registered subtype
        subtypeResolver.registerSubtypes(Sub.class);

        Collection<NamedType> result = subtypeResolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        // Since Sub is both in annotation and registered, typesHandled Set should prevent duplicates in final output
        long subCount = result.stream().filter(nt -> nt.getType().equals(Sub.class)).count();
        assertTrue("Should contain Sub type", subCount >= 1);
    }

    /**
     * Tests the case where findSubtypes returns an empty collection instead of null.
     */
    @Test
    public void testCollectSubtypes_EmptyAnnotationList() {
        when(mockBaseType.getRawClass()).thenReturn(Base.class);
        when(mockAi.findSubtypes(mockProperty)).thenReturn(new ArrayList<>());

        Collection<NamedType> result = subtypeResolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Base.class)));
    }
}
